# Test descriptions are in English. SQL assertions use the isolated test database.
assert_equals "products.id has the required type" "SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='products' AND COLUMN_NAME='id'" "int"
assert_equals "products.sku has the required type" "SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='products' AND COLUMN_NAME='sku'" "char(8)"
assert_equals "products.name has the required type" "SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='products' AND COLUMN_NAME='name'" "varchar(100)"
assert_equals "products.description has the required type" "SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='products' AND COLUMN_NAME='description'" "text"
assert_equals "products.price has the required type" "SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='products' AND COLUMN_NAME='price'" "decimal(8,2)"
assert_equals "products.stock has the required type" "SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='products' AND COLUMN_NAME='stock'" "int"
assert_equals "products.available_on has the required type" "SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='products' AND COLUMN_NAME='available_on'" "date"
assert_equals "products.created_at has the required type" "SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='products' AND COLUMN_NAME='created_at'" "datetime"
assert_equals "products.active has the required type" "SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='products' AND COLUMN_NAME='active'" "tinyint(1)"
assert_accepts "A product accepts realistic values" "INSERT INTO products VALUES(1,'00001234','Chitarra','Acustica',129.90,3,'2026-10-01','2026-10-01 09:30:00',TRUE)"
assert_equals "Money keeps its decimal precision" "SELECT price FROM products WHERE id=1" "129.90"
assert_rejects "An out of range price is rejected" "1264" "INSERT INTO products (price) VALUES (1000000.00)"
